Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -28,4 +28,45 @@
   <div class="bottom"><div class="objective" id="objective">Find the stairs. Descend deeper.</div><div class="keys"><span><i class="keycap">WASD</i> Move</span><span><i class="keycap">SPACE</i> Strike</span><span><i class="keycap">E</i> Potion</span><span><i class="keycap">SHIFT</i> Dash</span></div></div>
   <div class="touch-controls"><div class="dpad"><button class="touch-btn up" data-move="up">↑</button><button class="touch-btn left" data-move="left">←</button><button class="touch-btn down" data-move="down">↓</button><button class="touch-btn right" data-move="right">→</button></div><div class="mobile-actions"><button class="touch-btn action-btn dash" data-action="dash">DASH</button><button class="touch-btn action-btn attack" data-action="attack">STRIKE</button></div></div>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
+const W=25,H=19,T=32, overlay=document.getElementById('overlay'), toastEl=document.getElementById('toast');
+const ui={level:document.getElementById('level'),hpText:document.getElementById('hpText'),hpBar:document.getElementById('hpBar'),xpText:document.getElementById('xpText'),xpBar:document.getElementById('xpBar'),power:document.getElementById('power'),armor:document.getElementById('armor'),shards:document.getElementById('shards'),potions:document.getElementById('potions'),relicList:document.getElementById('relicList'),objective:document.getElementById('objective')};
+const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a, clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+let map=[],rooms=[],enemies=[],drops=[],particles=[],decor=[],depth=1,run=null,playing=false,last=0,toastTimer=0,shake=0;
+const keys={};
+const relicPool=[{name:'Emberheart',icon:'♥',desc:'Vitality +25',apply:p=>{p.maxHp+=25;p.hp+=25;}},{name:'Grave-Iron Ring',icon:'◈',desc:'Armor +1',apply:p=>p.armor++},{name:'Whetstone',icon:'⚔',desc:'Power +4',apply:p=>p.power+=4},{name:'Foxfire Charm',icon:'✦',desc:'Strike faster',apply:p=>p.attackRate=Math.max(.24,p.attackRate-.12)},{name:'Bloodroot',icon:'♧',desc:'Heal 35 vitality',apply:p=>p.hp=Math.min(p.maxHp,p.hp+35)}];
+function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');toastTimer=1.8}
+function freshRun(){run={x:0,y:0,hp:100,maxHp:100,level:1,xp:0,nextXp:30,power:12,armor:0,shards:0,potions:1,attackRate:.48,attackCd:0,attackAnim:0,dashCd:0,dashTime:0,invuln:0,faceX:1,faceY:0,relics:[],kills:0};depth=1;newFloor();overlay.classList.add('hidden');playing=true;uiUpdate();toast('THE DESCENT BEGINS')}
+function newFloor(){
+ map=Array.from({length:H},()=>Array(W).fill(0));rooms=[];enemies=[];drops=[];particles=[];decor=[];
+ const target=rand(6,8), tries=0;
+ for(let n=0;n<100&&rooms.length<target;n++){
+  const rw=rand(4,7),rh=rand(4,6),x=rand(1,W-rw-2),y=rand(1,H-rh-2);
+  if(rooms.some(r=>x<r.x+r.w+1&&x+rw+1>r.x&&y<r.y+r.h+1&&y+rh+1>r.y))continue;
+  const r={x,y,w:rw,h:rh,cx:x+Math.floor(rw/2),cy:y+Math.floor(rh/2)};rooms.push(r);
+  for(let yy=y;yy<y+rh;yy++)for(let xx=x;xx<x+rw;xx++)map[yy][xx]=1;
+ }
+ if(rooms.length<2){rooms=[{x:2,y:3,w:7,h:6,cx:5,cy:6},{x:15,y:9,w:7,h:6,cx:18,cy:12}];for(const r of rooms)for(let y=r.y;y<r.y+r.h;y++)for(let x=r.x;x<r.x+r.w;x++)map[y][x]=1;}
+ for(let i=1;i<rooms.length;i++){const a=rooms[i-1],b=rooms[i];if(Math.random()<.5){carveH(a.cx,b.cx,a.cy);carveV(a.cy,b.cy,b.cx)}else{carveV(a.cy,b.cy,a.cx);carveH(a.cx,b.cx,b.cy)}}
+ const start=rooms[0],end=rooms[rooms.length-1];run.x=(start.cx+.5)*T;run.y=(start.cy+.5)*T;
+ map[end.cy][end.cx]=2;
+ for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){
+  if(map[y][x]===1){if(Math.random()<.075)decor.push({x,y,type:Math.random()<.55?'rubble':'moss',seed:Math.random()});}
+ }
+ const candidates=[];for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++)if(map[y][x]===1&&Math.hypot(x-start.cx,y-start.cy)>4&&Math.hypot(x-end.cx,y-end.cy)>2)candidates.push({x,y});
+ const count=depth===3?Math.max(3,depth+2):depth+3;
+ for(let i=0;i<count&&candidates.length;i++){
+  const idx=rand(0,candidates.length-1),p=candidates.splice(idx,1)[0];
+  const type=depth===3&&i===0?'warden':Math.random()<(depth===1?.7:.45)?'crawler':'wraith';
+  const base=type==='warden'?{hp:115,damage:16,speed:45,size:13,xp:45,color:'#d06c4f'}:type==='crawler'?{hp:28+depth*7,damage:8+depth,speed:48+depth*3,size:9,xp:12,color:'#ad6655'}:{hp:20+depth*6,damage:7+depth,speed:35+depth*2,size:10,xp:14,color:'#8b83a6'};
+  enemies.push({...base,type,x:(p.x+.5)*T,y:(p.y+.5)*T,maxHp:base.hp,cd:rand(20,80)/100,hit:0});
+ }
+ ui.objective.textContent=depth===3?'Find the sealed stair. End the curse.':'Find the stairs. Descend deeper.';
+ document.querySelector('.floor-number').innerHTML=depth+'<span style="font-size:13px;color:#938876"> / 3</span>';
+}
+function carveH(a,b,y){for(let x=Math.min(a,b);x<=Math.max(a,b);x++)map[y][x]=1}function carveV(a,b,x){for(let y=Math.min(a,b);y<=Math.max(a,b);y++)map[y][x]=1}
+function wallAt(px,py){const x=Math.floor(px/T),y=Math.floor(py/T);return x<0||y<0||x>=W||y>=H||map[y][x]===0}
+function canOccupy(x,y,r=9){return !wallAt(x-r,y-r)&&!wallAt(x+r,y-r)&&!wallAt(x-r,y+r)&&!wallAt(x+r,y+r)}
+function uiUpdate(){if(!run)return;ui.level.textContent=run.level;ui.hpText.textContent=Math.ceil(run.hp)+' / '+run.maxHp;ui.hpBar.style.width=(100*run.hp/run.maxHp)+'%';ui.xpText.textContent=run.xp+' / '+run.nextXp;ui.xpBar.style.width=(100*run.xp/run.nextXp)+'%';ui.power.textContent=run.power;ui.armor.textContent=run.armor;ui.shards.textContent=run.shards;ui.potions.textContent=run.potions;ui.relicList.innerHTML=run.relics.length?run.relics.map(r=>`<div class="relic"><div class="relic-icon">${r.icon}</div><div><div class="relic-name">${r.name}</div><div class="relic-desc">${r.desc}</div></div></div>`).join(''):'<div class="empty-relic">The deep keeps its treasures close.</div>'}

input.newString:
function uiUpdate(){if(!run)return;ui.level.textContent=run.level;ui.hpText.textContent=Math.ceil(run.hp)+' / '+run.maxHp;ui.hpBar.style.width=(100*run.hp/run.maxHp)+'%';ui.xpText.textContent=run.xp+' / '+run.nextXp;ui.xpBar.style.width=(100*run.xp/run.nextXp)+'%';ui.power.textContent=run.power;ui.armor.textContent=run.armor;ui.shards.textContent=run.shards;ui.potions.textContent=run.potions;ui.relicList.innerHTML=run.relics.length?run.relics.map(r=>`<div class="relic"><div class="relic-icon">${r.icon}</div><div><div class="relic-name">${r.name}</div><div class="relic-desc">${r.desc}</div></div></div>`).join(''):'<div class="empty-relic">The deep keeps its treasures close.</div>'}
function addXp(n){run.xp+=n;while(run.xp>=run.nextXp){run.xp-=run.nextXp;run.level++;run.nextXp=Math.floor(run.nextXp*1.45);run.maxHp+=12;run.hp=Math.min(run.maxHp,run.hp+30);run.power+=2;toast('LEVEL UP · POWER +2 · VITALITY RESTORED');}uiUpdate()}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=rand(25,120);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.38,max:.63,color,size:rand(1,3)})}}
function attack(){if(!playing||run.attackCd>0)return;run.attackCd=run.attackRate;run.attackAnim=.18;let hit=false;for(const e of [...enemies]){const dx=e.x-run.x,dy=e.y-run.y,d=Math.hypot(dx,dy),dot=(dx*run.faceX+dy*run.faceY)/(d||1);if(d<43+e.size&&dot>-.15){e.hp-=run.power+rand(-2,3);e.hit=.13;hit=true;burst(e.x,e.y,'#e6bc74',5);if(e.hp<=0){enemies.splice(enemies.indexOf(e),1);run.kills++;addXp(e.xp);if(Math.random()<.58)drops.push({x:e.x,y:e.y,type:'shard',amount:rand(2,6)});if(Math.random()<.14)drops.push({x:e.x,y:e.y,type:'potion'});if(e.type==='warden'){drops.push({x:e.x,y:e.y,type:'relic'});toast('THE WARDEN FALLS · A RELIC IS YOURS');}else if(Math.random()<.12)drops.push({x:e.x,y:e.y,type:'relic'});}}}if(hit)shake=3}
function takePotion(){if(!playing||run.potions<1||run.hp>=run.maxHp)return;run.potions--;const healed=Math.min(45,run.maxHp-run.hp);run.hp+=healed;burst(run.x,run.y,'#8dc689',12);toast('POTION · +'+healed+' VITALITY');uiUpdate()}
function doDash(){if(!playing||run.dashCd>0)return;run.dashCd=1.2;run.dashTime=.16;run.invuln=.22;burst(run.x,run.y,'#c7ab82',6)}
function damage(n){if(run.invuln>0)return;run.hp-=Math.max(1,n-run.armor*2);run.invuln=.65;shake=7;burst(run.x,run.y,'#cf6155',9);uiUpdate();if(run.hp<=0){run.hp=0;uiUpdate();playing=false;showEnd(false)}}
function pickup(d){if(d.type==='shard'){run.shards+=d.amount;toast('ASHEN SHARDS +'+d.amount)}else if(d.type==='potion'){run.potions++;toast('POTION FOUND')}else{const r=relicPool[rand(0,relicPool.length-1)];r.apply(run);run.relics.push(r);toast('RELIC FOUND · '+r.name.toUpperCase())}uiUpdate()}
function showEnd(win){overlay.classList.remove('hidden');document.getElementById('modalTitle').innerHTML=win?'The Hollow<br>Remembers':'Lost to the deep';document.querySelector('.eyebrow').textContent=win?'A curse undone':'Your light has gone out';document.getElementById('modalCopy').textContent=win?`The warden is silent. You leave the hollow with ${run.shards} ashen shards and ${run.kills} fallen foes. The old halls will remember your name.`:`You reached depth ${depth} and felled ${run.kills} foes. The hollow takes your shards, but every descent teaches the way.`;document.getElementById('startBtn').textContent='Descend again';document.querySelector('.hint').textContent='EVERY DESCENT IS DIFFERENT · YOUR STORY IS YOURS'}
function descend(){if(depth>=3){playing=false;showEnd(true);return}depth++;newFloor();run.hp=Math.min(run.maxHp,run.hp+20);uiUpdate();toast('DEPTH '+depth+' · THE AIR GROWS COLDER')}

