input.newString:
function descend(){if(depth>=3){playing=false;showEnd(true);return}depth++;newFloor();run.hp=Math.min(run.maxHp,run.hp+20);uiUpdate();toast('DEPTH '+depth+' · THE AIR GROWS COLDER')}
function update(dt){if(!playing)return;run.attackCd=Math.max(0,run.attackCd-dt);run.attackAnim=Math.max(0,run.attackAnim-dt);run.dashCd=Math.max(0,run.dashCd-dt);run.dashTime=Math.max(0,run.dashTime-dt);run.invuln=Math.max(0,run.invuln-dt);if(toastTimer>0&&(toastTimer-=dt)<=0)toastEl.classList.remove('show');let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;run.faceX=dx;run.faceY=dy;const sp=run.dashTime>0?390:142;let nx=run.x+dx*sp*dt,ny=run.y+dy*sp*dt;if(canOccupy(nx,run.y))run.x=nx;if(canOccupy(run.x,ny))run.y=ny}
 for(const e of enemies){e.cd-=dt;if(e.hit>0)e.hit-=dt;const d=dist(e,run);if(d>e.size+12){const vx=(run.x-e.x)/(d||1),vy=(run.y-e.y)/(d||1),sp=e.speed*(e.type==='warden'&&e.hp<e.maxHp/2?1.25:1);let nx=e.x+vx*sp*dt,ny=e.y+vy*sp*dt;if(canOccupy(nx,e.y,e.size*.75))e.x=nx;if(canOccupy(e.x,ny,e.size*.75))e.y=ny}else if(e.cd<=0){damage(e.damage);e.cd=e.type==='warden'?.9:1.05}}
 for(let i=drops.length-1;i>=0;i--){if(dist(drops[i],run)<19){pickup(drops[i]);drops.splice(i,1)}}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}
 const tx=Math.floor(run.x/T),ty=Math.floor(run.y/T);if(map[ty]?.[tx]===2){descend()}}
function draw(){ctx.clearRect(0,0,W*T,H*T);const ox=0,oy=0;ctx.fillStyle='#111214';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=map[y][x],px=x*T,py=y*T;if(t===0){ctx.fillStyle=((x*7+y*13)%5===0)?'#111214':'#141416';ctx.fillRect(px,py,T,T);if((x+y*3)%17===0){ctx.strokeStyle='#19191b';ctx.beginPath();ctx.moveTo(px+5,py+20);ctx.lineTo(px+13,py+17);ctx.stroke()}}else{ctx.fillStyle=((x*7+y*13)%3===0)?'#292827':'#262524';ctx.fillRect(px,py,T,T);ctx.fillStyle='#302e2b';ctx.fillRect(px+2,py+2,T-4,T-4);if((x*3+y*5)%4===0){ctx.fillStyle='#33312e';ctx.fillRect(px+3,py+3,11,1)}if(t===2){ctx.fillStyle='#493924';ctx.fillRect(px+1,py+1,T-2,T-2);ctx.strokeStyle='#b88a4d';ctx.lineWidth=2;ctx.strokeRect(px+4,py+4,T-8,T-8);ctx.fillStyle='#dbb36d';ctx.beginPath();ctx.arc(px+16,py+16,7+Math.sin(performance.now()/220)*1.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0c4';ctx.beginPath();ctx.arc(px+16,py+16,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2c2520';ctx.font='10px sans-serif';ctx.fillText('↓',px+12,py+20)}}}
